+LEDGER=$t bash src/move.sh A-100 0 IN PO-1 >/dev/null 2>&1; [ $? = 2 ] || { echo "0 accepted"; fail=1; }
+LEDGER=$t bash src/move.sh A-100 -3 IN PO-1 >/dev/null 2>&1; [ $? = 2 ] || { echo "-3 accepted"; fail=1; }
